    'tutorial.coachTreeTitle': 'Prueba la otra rama principal',
    'tutorial.coachTreeCopy': 'Solo se compartió Dinosauria con <em>Triceratops</em>, por lo que Ornithischia queda descartado. Prueba <em>Brachiosaurus</em>, un sauropodomorfo dentro de Saurischia y Eusaurischia.',
    'tutorial.coachHintTitle': 'Interpreta Eusaurischia',
