    'howto.intro': 'Jeden Tag wird ein Dinosaurier gesucht. Dein Ziel ist es, ihn anhand der Hinweise zu bestimmen, die deine Tipps aufdecken.',
    'howto.step1': '1. Rate eine Gattung',
    'howto.step1Copy': 'Gib einen beliebigen Dinosauriernamen ein und sende ihn ab. Der Stammbaum zeigt, wie nah dein Tipp mit dem gesuchten Dinosaurier verwandt ist.',
    'howto.step2': '2. Lies den Stammbaum',
    'howto.step2Copy': 'Jeder Tipp zeigt die tiefste Klade, die er mit dem gesuchten Dinosaurier gemeinsam hat. Je näher im Stammbaum, desto wärmer bist du.',
    'howto.step3': '3. Hinweise',
    'howto.step3Copy': 'Für jede Herausforderung hast du 3 Hinweise. Sie zeigen die nächste Klade und, sobald die gesamte Abstammungslinie bekannt ist, Hinweise zum Gattungsnamen. Zwischen zwei Hinweisen musst du 2 Tipps abgeben.',
    'howto.step4': '4. Fünf Schwierigkeitsstufen',
    'howto.step4Copy': 'In Stufe I findest du bekannte Gattungen. Stufe V umfasst weniger bekannte Taxa, für die breites taxonomisches Wissen nötig ist.',
    'howto.tip': 'Gut zu wissen',
    'howto.tipCopy': 'Klicke auf einen beliebigen Knoten im Stammbaum, um mehr über die Klade zu erfahren. Neu hier? Beginne mit Stufe I.',
    'howto.noLimit': 'Während ich prüfe, welche Begrenzung am ausgewogensten wäre, gibt es im Spiel derzeit kein Tipp-Limit. Das kann sich in zukünftigen Updates ändern.',
    'tutorial.interactive': 'Tutorial spielen',
