    'tutorial.tryFirst': 'Probiere zuerst den Tipp aus',
    'tutorial.guessRevealed': 'Tipp aufgedeckt',
    'tutorial.loading': 'Tutorial wird vorbereitet…',
    'tutorial.loadError': 'Das Tutorial konnte nicht geladen werden.',
    'tutorial.context': 'Anleitung',
    'tutorial.restart': 'Neu starten',
    'tutorial.repeat': 'Tutorial wiederholen',
    'tutorial.return': 'Zurück',
    'tutorial.tryTitle': 'Folge dem angeleiteten Zug',
    'tutorial.tryExpected': 'Wähle für diesen Schritt <em>{name}</em> aus den Vorschlägen.',
    'tutorial.followCoach': 'Folge dem hervorgehobenen Schritt, bevor du diese Steuerung verwendest.',
    'tutorial.coachFirstTitle': 'Ornithischia untersuchen',
    'tutorial.coachFirstCopy': 'Beginne mit <em>Triceratops</em>. Seine Abstammungslinie führt durch Ornithischia. Wenn der Stammbaum nur Dinosauria zeigt, gehört das gesuchte Tier nicht zu diesem Ast.',
    'tutorial.coachTreeTitle': 'Den anderen Hauptast untersuchen',
    'tutorial.coachTreeCopy': 'Mit <em>Triceratops</em> wurde nur Dinosauria geteilt; Ornithischia ist also ausgeschlossen. Probiere <em>Brachiosaurus</em>, einen Sauropodomorphen innerhalb von Saurischia und Eusaurischia.',
    'tutorial.coachHintTitle': 'Eusaurischia deuten',
    'tutorial.coachHintCopy': '<em>Brachiosaurus</em> teilt Saurischia und Eusaurischia mit dem gesuchten Tier, aber dessen Abstammungslinie führt nicht durch Sauropodomorpha. Nutze den Hinweis, um herauszufinden, welcher Ast der Eusaurischia weiterführt.',
    'tutorial.coachCloserTitle': 'Theropoda genauer untersuchen',
    'tutorial.coachCloserCopy': 'Der Hinweis hat Theropoda aufgedeckt. Probiere <em>Tyrannosaurus</em>, um zu sehen, wie weit das gesuchte Tier dem Ast der Coelurosaurier folgt.',
    'tutorial.coachSolveTitle': 'Den Ast hinter Tyrannoraptora wählen',
    'tutorial.coachSolveCopy': '<em>Tyrannosaurus</em> teilt die Abstammungslinie bis Tyrannoraptora und folgt dann Tyrannosauroidea. Das gesuchte Tier nimmt hinter Tyrannoraptora einen anderen Ast. Probiere <em>Velociraptor</em>.',
    'tutorial.completeKicker': 'Tutorial abgeschlossen',
    'tutorial.completeTitle': 'Ziel bestimmt',
    'tutorial.completeCopy': 'Die Abfolge schloss zuerst Ornithischia und dann Sauropodomorpha aus und folgte Theropoda bis Tyrannoraptora. Dieses Tutorial verändert weder deine Statistiken noch das Museum.',
    'tutorial.playLevelOne': 'Stufe I spielen',
