    'museum.atlasIntro': 'Die Gattungen im Museum sind in der aktuellen Klassifikation drei großen Kladen zugeordnet. Die Zählung richtet sich nach der gespeicherten Abstammungslinie jeder Gattung.',
    'museum.atlasTheropoda': 'Eine saurischische Klade, deren Vorfahren sich durch zweibeinige Fortbewegung auszeichneten. Sie umfasst Ceratosauria, Tetanurae und Avialae.',
